let wordState=freshWordState();try{const s=JSON.parse(localStorage.getItem(WORD_KEY)||'null');if(s&&s.records&&typeof s.records==='object')wordState=sanitizeWordState(s)}catch{}
if(![0,...WORD_LEVELS.map(([n])=>n)].includes(wordState.level))wordState.level=0;
