const FREQ_BANDS=[['top','最高',9],['high','高',7],['mid','中',4],['low','低',1]];
function freqBand(n){return (FREQ_BANDS.find(b=>n>=b[2])||FREQ_BANDS[FREQ_BANDS.length-1])[0]}
function freqLabel(n){return (FREQ_BANDS.find(b=>n>=b[2])||FREQ_BANDS[FREQ_BANDS.length-1])[1]}
