let phraseQuery='';
const SLANG_TOPIC_INFO=[['一般','よく使う口語','友達どうしでよく聞く口語・くだけた言い方'],['友達の日常','友達の日常','いっしょに過ごすときの言い回し'],['ほめる・反応','ほめる・反応','すごい・ウケる・いいね、などの反応'],['気持ち','気持ち','うれしい・つらい・だるい、などの気分'],['誘う・返す','誘う・返す','誘い方と、OK・断りの返し方'],['遊ぶ・飲む','遊ぶ・飲む','飲み会・遊びの場面の言葉'],['恋愛・人間関係','恋愛・人間関係','好き・付き合う・別れる、人との関係'],['ネット・SNS','ネット・SNS','ネット・SNSの書き方と言い回し'],['下ネタ','下ネタ','大人の会話の語。相手と場面を選ぶ'],['粗い言葉','粗い言葉','乱暴な言い方。意味を知っておくための語'],['差別的表現','差別的表現','人を傷つける言い方。理解のためだけに収録']];
const SLANG_NO_STEP=new Set(['s:差別的表現']);const SLANG_CAUTION={'s:粗い言葉':'乱暴な言い方です。相手との関係によってはけんかになります。','s:差別的表現':'人を傷つける言い方です。意味を知るためだけに使い、自分では使わないでください。覚えるステップは用意していません。','s:下ネタ':'大人どうしの会話の語です。相手と場面を選んでください。'};
function slangTopics(){return [...SLANG_TOPIC_INFO.map(([cat,label,description])=>({id:'s:'+cat,label,description,cat})),{id:'s:trend',label:'流行語・新語',description:'時期と結びついた流行語と、新しい言い方'}]}
const PHRASE_SCENES=[{id:'p:greet',label:'あいさつ・お礼',description:'こんにちは・ありがとう・ごめんね・またね'},{id:'p:react',label:'相づち・リアクション',description:'うん・へえ・すごい・えっ、などの反応'},{id:'p:ask',label:'たずねる',description:'どこ？・いくら？・本当？などの聞き方'},{id:'p:no',label:'返事・断る',description:'はい・いいえ・大丈夫・まだ、などの返し方'},{id:'p:time',label:'時間の言い回し',description:'しばらく・これから・その時、など'},{id:'p:shop',label:'お金・買い物',description:'値切る・割引・支払いの言い方'},{id:'p:link',label:'つなぎ・文の型',description:'だから・それとも・〜にもかかわらず'},{id:'p:other',label:'いろいろな言い回し',description:'その他のよく使う決まった言い方'}];
