function setDictionaryQuery(value){wordQuery=value;wordPage=0;const browse=document.getElementById('word-browse');if(browse)browse.hidden=!!wordQuery.trim();refreshWordList()}
function selectedWords(){let out=bank.filter(w=>wordInDeck(w)&&wordInLevel(w)&&wordInTopic(w)&&(wordDeck!=='phrase'||!phraseQuery.trim()||wordMatches(w,phraseQuery))).map(w=>topicWord(w)).filter(w=>(wordScope==='all'||wordScope==='favorites'&&wordRec(w.id).favorite||wordScope==='review'&&dueWord(w))&&(!wordPos||w.meanings.some(s=>s.pos===wordPos))&&(!wordCategory||(wordCategory==='trend'?!!wordTrend(w):w.category===wordCategory))&&(!wordFrequency||freqBand(w.frequency)===wordFrequency)&&wordMatches(w,wordQuery));const sorters={'frequency-desc':(a,b)=>b.frequency-a.frequency||a.corpusRank-b.corpusRank,'frequency-asc':(a,b)=>a.frequency-b.frequency||b.corpusRank-a.corpusRank,'thai':(a,b)=>a.th.localeCompare(b.th,'th'),'pos':(a,b)=>a.pos.localeCompare(b.pos,'ja')||b.frequency-a.frequency,'category':(a,b)=>wordTopicLabel(a).localeCompare(wordTopicLabel(b),'ja')||b.frequency-a.frequency,'unseen':(a,b)=>(wordRec(a.id).seen>0)-(wordRec(b.id).seen>0)||b.frequency-a.frequency,'due':(a,b)=>(wordRec(a.id).due||Infinity)-(wordRec(b.id).due||Infinity)||b.frequency-a.frequency};return out.sort(sorters[wordSort]||sorters['frequency-desc'])}
