function refreshWordList(){const el=document.getElementById('word-results');if(el)el.innerHTML=wordListHTML()}
function relationPresentation(w,type,id){const target=bankMap.get(id),detail=(w.relationDetails?.[type]||[]).find(d=>d.id===id);const targetMeanings=(detail?.targetSenses||[]).map(n=>target.meanings.find(m=>m.sourceSense===n)).filter(Boolean);const sourceMeanings=(detail?.sourceSenses||[]).map(n=>w.meanings.find(m=>m.sourceSense===n)).filter(Boolean);return {target,meanings:targetMeanings.length?targetMeanings:[target.meanings[0]],context:sourceMeanings.map(m=>m.ja).join('／')}}
function relationBlock(w,type,title){const xs=(w.relations[type]||[]).filter(id=>bankMap.has(id)).map(id=>relationPresentation(w,type,id));return `<div class="w-relation"><h3>${title}</h3>${xs.length?`<div class="w-related">${xs.map(({target:x,meanings,context})=>`<button onclick="openWord('${x.id}')"><span lang="th">${esc(x.th)}</span><b>${esc(x.ro)}</b><small>${esc(meanings.map(m=>m.ja).join('／'))}</small>${context&&w.meanings.length>1?`<em class="w-relation-context">「${esc(context)}」の${title}</em>`:''}</button>`).join('')}</div>`:'<p>この語の関係は未収録です。</p>'}</div>`}
// 成り立ち: a headword made of registered words (รถไฟ = รถ + ไฟ). The split must use every character and give the
