function shortGloss(w,whole=null){const ms=w.meanings.filter(m=>!m.isSlang&&!PART_SKIP_POS.has(m.pos)),all=ms.length?ms:w.meanings,wj=whole?whole.meanings.map(m=>m.ja).join(''):'',hit=wj?all.find(m=>[...m.ja.replace(/（[^）]*）/g,'')].some(c=>/[\u3400-\u9fff]/.test(c)&&wj.includes(c))):null,first=s=>String(s.ja).replace(/（[^）]*）/g,'').split(/[・、,，;；/／]/)[0].trim().slice(0,14);return hit?first(hit):first(all[0])+(whole&&all.length>1?' など':'')}
function wordPartsSection(w){const ps=wordParts(w);if(!ps.length)return '';return `<section class="w-parts" aria-label="成り立ち"><h2><span class="w-parts-icon" aria-hidden="true">${icon('course')}</span>成り立ち</h2><div class="w-parts-row">${ps.map((x,i)=>`${i?'<span class="w-parts-plus" aria-hidden="true">+</span>':''}<button class="w-part" onclick="openWord('${x.id}')" aria-label="${esc(x.th)}（${esc(shortGloss(x,w))}）を開く"><b lang="th">${esc(x.th)}</b><small lang="th-Latn">${esc(x.ro)}</small><span>${esc(shortGloss(x,w))}</span></button>`).join('')}</div></section>`}
function wordDetail(){const w=topicWord(bankMap.get(wordCurrent)),r=wordRec(w.id);return `<button class="textbtn back" onclick="backWords()">← ${wordTrail.length?'前の単語':'単語一覧'}に戻る</button><article class="w-detail"><div class="w-detail-head"><div><h1 lang="th">${esc(w.th)}</h1><div class="w-detail-ro">${esc(w.ro)}</div>${wordMeta(w)}${wordRegister(w)}</div><div class="w-detail-audio">${wordAudio(w.id)}</div></div><div class="w-detail-actions"><button class="btn light x-fav ${r.favorite?'chosen':''}" onclick="favoriteWord('${w.id}')" aria-label="お気に入り${r.favorite?'から外す':'に登録'}" aria-pressed="${r.favorite}" title="お気に入り">${icon('star')}</button><button class="btn light x-rev ${r.manual?'chosen':''}" onclick="reviewWord('${w.id}')" aria-label="復習${r.manual?'から外す':'に登録'}" aria-pressed="${r.manual}" title="復習に登録">${icon('review')}復習</button></div>${wordPartsSection(w)}${wordOriginDetails(w)}<section class="w-meanings"><div class="section-head"><h2>意味と使い方</h2><span>よく使う意味から</span></div>${w.meanings.map((s,i)=>`<div class="w-sense"><span class="w-sense-no">${i+1}</span><div><h3>${esc(s.ja)}</h3><div class="w-sense-meta"><span>${esc(s.pos)}</span>${s.ro&&s.ro!==w.ro?`<span class="w-speech-style">この意味の読み：${esc(s.ro)}</span>`:''}<span>${s.use}</span>${s.speechStyle?`<span class="w-speech-style">${esc(styleLabel(s.speechStyle))}</span>`:''}${wordOriginBadge(w,s)}${s.checked?'':`<span class="w-reference">${s.reviewStatus==='needs-source'?'要確認':'参考訳'}</span>`}</div>${s.note?`<p class="w-usage-note">${esc(s.note)}</p>`:''}<details ${s.en?'':'hidden'}><summary>元の英語語義を確認</summary><p>${esc(s.en)}</p>${s.checked?'':'<p>この日本語訳には英語語義からの自動翻訳・辞書を介した参考訳を含みます。文脈によって意味が変わります。</p>'}</details>${wordSenseExample(w,s,i)}</div></div>`).join('')}</section><section class="w-relations"><div class="section-head"><h2>つながりで覚える</h2><span>タップして移動</span></div>${relationBlock(w,'ant','対義語')}${relationBlock(w,'syn','類義語')}${(w.relations.similar||[]).length?relationBlock(w,'similar','混同しやすい語'):''}${(w.relations.related||[]).length?relationBlock(w,'related','関連語'):''}<p class="subtext">語義によって成立する関係です。類義語がすべての文脈で置き換えられるとは限りません。</p></section>${r.seen?`<div class="w-memory"><span>学習 ${r.seen}回</span><span>正解 ${r.correct}回</span><span>次の復習：${r.due<=Date.now()?'今':new Date(r.due).toLocaleDateString('ja-JP')}</span></div>`:''}</article>`}
function wordSources(){return `<details class="w-sources"><summary>収録語・語源・確認状況について</summary><p>語源は辞書で借用・由来の記載が確認できた語義に表示します。同語源の類似語は借用元とは区別します。語源未確認の語もあります。<a href="origin-review.json" target="_blank" rel="noopener">今回の照合範囲・確認状況 ↗</a></p><p>テーマは語の一般的な意味をもとに分類し、複数のテーマに載る語もあります。テーマを選ぶと、そのテーマに対応する意味・用例を一覧・カード・テストで優先します。スラングの学習欄とは分けています。狭い学習範囲で選択肢が足りない場合のみ、同じ範囲の別テーマからも選択肢を補います。</p><p>学習範囲（基本500・日常1,000・会話3,000・発展5,000語）は、元の学習段階、頻度、会話コーパス順位の順で一般語を並べた累積範囲です。元の一般語4,969語は5,000語までに入り、追加語は頻度表の順にその後ろへ並びます。公的な語彙レベルや頻度上位そのものを示すものではありません。範囲は一覧・カード・テストに適用し、スラングは別に学習します。</p><p>カタカナ検索は、声調付きローマ字から作った検索用の近似読みと、よくある表記を使います。長音・区切り・濁音の揺れを吸収します。正確な発音はローマ字と音声で確認してください。</p><p>5,000語・表現は、ThaiReader「Thai learner word list, release v42」から固有名詞を除き、学習段階と会話コーパスの順位をもとに選択しました。頻度の最高・高・中・低は、基本語では会話頻度の順位による相対的な目安です（最高はおおむね上位1,000語、高はその次の1,000語、中はその次の1,500語、低はそれ以降）。追加語は書き言葉・ウェブのコーパスの出現数をこの目盛りに合わせた推定で、書き言葉寄りの語は低めに抑え、複合語は構成する語より高くしていません。まとまりとして計測されていない表現は元データの学習段階から推定します。</p><p>意味は元データの dominant → common → rare の順。個別の場面での厳密な使用率を示すものではありません。日本語訳は既存の学習語彙・日本語版Wiktionary・英和辞書・英語語義からの自動翻訳を組み合わせています。未校閲の参考訳は詳細に表示します。元データ自体も草稿を含みます。</p>${bank.some(w=>w.expansion)?`<p>追加語（${bank.filter(w=>w.expansion).length.toLocaleString()}語）は、newthai Textbooks Frequency List v2.4 の候補から、日本語訳・読み・用例をAIが作成し、別担当のAIが1語ずつ点検して合格したものです。ネイティブ話者の校閲ではありません。書き言葉寄りの頻度表に基づくため、文語・改まった語・王室の語を含み、その区分を各語に表示します。頻度は頻度表の順位からの推定です。学習範囲では元の語の後ろに並び、3,000語までの範囲には入りません。<a href="expansion-review.json" target="_blank" rel="noopener">追加語の点検結果 ↗</a></p>`:''}<p>別欄のスラング集は207項目。うち122項目は日本語説明・用例を今回作成し、既存の俗語用法も分離しました。スラング欄の頻度は友達との会話での編集上の目安です。口語とスラングは同義ではなく、性的な話題でも標準語の場合はその旨を表示します。</p><p>2026年11月10日に全5,000件のデータ整合性を点検し、917見出し・993語義の日本語を個別に見直しました。全語の辞書照合・ネイティブ校閲は未完了です。<a href="vocabulary-review.json" target="_blank" rel="noopener">点検範囲を確認</a>　<a href="quality-review.json" target="_blank" rel="noopener">追加点検の内容</a></p><p>関係がない語に対義語・類義語を作って付けてはいません。未収録の関係は「未収録」と表示します。音声は端末のタイ語読み上げを使います。</p><p><a href="sources.html" target="_blank" rel="noopener">出典・ライセンス・加工方法 ↗</a>　<a href="word-bank.json" download>語彙データ（CC BY-SA 4.0）↓</a></p></details>`}
let wordQuizMode='th-ja';
function pickSessionWords(pool,n,now=Date.now()){const priority=w=>{const r=wordRec(w.id);return r.seen&&r.due<=now?0:!r.seen?1:2};return [...pool].sort((a,b)=>priority(a)-priority(b)||((wordRec(a.id).due||0)-(wordRec(b.id).due||0))||b.frequency-a.frequency||a.corpusRank-b.corpusRank).slice(0,n)}
function makeWordQuestion(w){w=topicWord(w);if(!w.meanings[0].checked)throw Error('参考訳はテスト対象外です');const norm=s=>foldWord(s).replace(/[、,・;；。\s]/g,''),meanings=new Set(w.meanings.map(s=>norm(s.ja)));const atoms=s=>s.split(/[・、,;；/／（）()]/).map(norm).filter(x=>x.length>=2&&!/^[〜…~]+$/.test(x)),knownAtoms=new Set(w.meanings.flatMap(m=>atoms(m.ja)));const avoid=new Set([w.id,...(w.relations.syn||[]),...(w.relations.similar||[])]);const acceptable=x=>!avoid.has(x.id)&&!x.meanings.some(s=>meanings.has(norm(s.ja))||atoms(s.ja).some(a=>knownAtoms.has(a)));let pool=bank.map(x=>topicWord(x)).filter(x=>wordInTopic(x)&&wordInDeck(x,w.collection==='slang'?'slang':'general')&&!!x.adult===!!w.adult&&x.th!==w.th&&wordInLevel(x)&&x.meanings[0].checked&&x.pos===w.pos&&x.category===w.category&&acceptable(x));if(pool.length<3)pool=bank.map(x=>topicWord(x)).filter(x=>wordInTopic(x)&&wordInDeck(x,w.collection==='slang'?'slang':'general')&&!!x.adult===!!w.adult&&x.th!==w.th&&wordInLevel(x)&&x.meanings[0].checked&&acceptable(x));if(pool.length<3)pool=bank.map(x=>topicWord(x)).filter(x=>wordInDeck(x,w.collection==='slang'?'slang':'general')&&!!x.adult===!!w.adult&&x.th!==w.th&&wordInLevel(x)&&x.meanings[0].checked&&acceptable(x));const selected=shuffle(pool).slice(0,3);if(selected.length<3)throw Error('出題候補が不足しています');return shuffle([w,...selected]).map(x=>x.id)}
// Step learning: the general deck in study order (frequency first), a fixed number of new words per step
// (the 1回の語数 setting). A step's check test with full marks moves on to the next step.
const localDate=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function stepOrder(){return bank.filter(w=>wordInDeck(w,'general')&&w.studyRank).sort((a,b)=>a.studyRank-b.studyRank)}
function stepLimit(){const n=stepOrder().length;return wordState.level?Math.min(wordState.level,n):n}
function nextStepWords(){return stepOrder().slice(wordState.stepWords,Math.min(wordState.stepWords+wordState.dailyGoal,Math.max(stepLimit(),wordState.stepWords+1)))}
function stepNumber(){return Math.floor(wordState.stepWords/wordState.dailyGoal)+1}
function stepsToday(){return wordState.today.date===localDate()?wordState.today.steps:0}
function startStep(kind){const ids=nextStepWords().map(w=>w.id);if(!ids.length)return;const from=wordState.stepWords,n=stepNumber();wordTopic='';startWords(kind,ids);if(wordSession)wordSession.step={from,ids,n}}
function markStudyDay(){const today=localDate(),y=new Date();y.setDate(y.getDate()-1);wordState.today={date:today,steps:stepsToday()+1};
 if(wordState.streak.last!==today)wordState.streak={last:today,days:wordState.streak.last===localDate(y)?wordState.streak.days+1:1};saveWords()}
function completeStep(s){if(wordState.stepWords!==s.step.from)return false;wordState.stepWords+=s.step.ids.length;markStudyDay();return true}
function streakDays(){const y=new Date();y.setDate(y.getDate()-1);return [localDate(),localDate(y)].includes(wordState.streak.last)?wordState.streak.days:0}
function stepPanel(){if(wordDeck!=='general'||bankStatus!=='ready')return '';const limit=stepLimit(),done=Math.min(wordState.stepWords,limit),next=nextStepWords(),finished=wordState.stepWords>=limit,today=stepsToday(),goalMet=today>=wordState.stepsPerDay,due=bank.filter(w=>wordInDeck(w,'general')&&dueWord(w)).length,streak=streakDays();
 return `<section class="x-step" aria-label="ステップ学習"><div class="x-step-main">${progressRing(done/limit,done.toLocaleString(),'ステップ学習の進み具合')}<div class="x-step-text"><h2>${finished?'この範囲は完了':`ステップ ${stepNumber()}`}</h2><p>${goalMet?'<b class="x-step-done">✓ 今日の分は完了</b>':`今日 <b>${today}</b> / ${wordState.stepsPerDay}`}${streak?` · 連続 <b>${streak}</b>日`:''} · ${esc(levelName())} ${done.toLocaleString()} / ${limit.toLocaleString()}語</p>${finished?'<p>範囲を広げると続きに進めます。</p>':`<p class="x-step-preview" lang="th-Latn">${next.map(w=>esc(w.ro)).join(' · ')}</p>`}</div></div>
 ${finished?'':`<div class="x-step-actions"><button class="btn x-step-go" onclick="startGuidedStep()">${due?`復習 ${due}語 ＋ 新しい語 ${next.length}語`:`新しい語 ${next.length}語`}を始める →</button></div>`}
 <details class="x-step-more"><summary>しくみと設定</summary><p>復習の時期が来た語 → 新しい語を音・意味・用例で見る → タイ語から意味を思い出す → 意味からタイ語を思い出す、の順に進みます。間違えた問題は少しあとにもう一度出ます。間隔を空けて思い出すほど記憶に残るので、復習は1・3・7・14・30・60日後に出ます。</p><div class="x-step-foot"><label>1日に<select class="field" onchange="wordState.stepsPerDay=Number(this.value);saveWords();render()">${[1,2,3].map(n=>`<option value="${n}" ${wordState.stepsPerDay===n?'selected':''}>${n}</option>`).join('')}</select>ステップ</label><label><input type="checkbox" ${wordState.autoplay!==false?'checked':''} onchange="wordState.autoplay=this.checked;saveWords()">自動で発音</label>${finished?'':`<button class="textbtn" onclick="startStep('cards')">カードだけ見る</button>`}</div></details></section>`}
function startWords(kind,onlyIds=null){let pool=onlyIds?onlyIds.map(id=>bankMap.get(id)).filter(Boolean).map(w=>topicWord(w)):selectedWords();if(!pool.length){toast('学習する単語がありません。表示範囲や条件を変えてください。');return}if(kind==='quiz'){const total=pool.length;pool=pool.filter(w=>w.meanings[0].checked);if(!pool.length){toast('この条件にはテストできる語がありません。参考訳は確認が終わるまで出題を控えています。');return}if(pool.length<total)toast('参考訳を除いた語から出題します。')}const selected=onlyIds?pool:pickSessionWords(pool,wordState.dailyGoal);wordSession={kind,topic:wordTopic,mode:wordQuizMode,ids:selected.map(w=>w.id),i:0,revealed:false,answered:null,results:[],choices:kind==='quiz'?makeWordQuestion(selected[0]):[],started:Date.now()};wordCurrent=null;render();window.scrollTo(0,0)}
function applyWordResult(id,correct,now=Date.now()){const r={...wordRec(id)},days=[1,3,7,14,30,60];r.seen++;r.last=now;if(correct){r.correct++;r.stage=Math.min((r.stage||0)+1,6);r.due=now+days[r.stage-1]*86400000}else{r.wrong++;r.lapses++;r.stage=0;r.due=now}wordState.records[id]=r;saveWords()}
function answerWord(id){if(!wordSession||wordSession.kind!=='quiz'||wordSession.answered!==null||!wordSession.choices.includes(id))return;const target=wordSession.ids[wordSession.i],ok=id===target;wordSession.answered=id;wordSession.results.push({id:target,correct:ok});applyWordResult(target,ok);render()}
function assessCard(ok){if(!wordSession?.revealed)return;const id=wordSession.ids[wordSession.i];wordSession.results.push({id,correct:ok});applyWordResult(id,ok);nextWordQuestion()}
function nextWordQuestion(){if(!wordSession)return;wordSession.i++;wordSession.revealed=false;wordSession.answered=null;if(wordSession.i<wordSession.ids.length&&wordSession.kind==='quiz')wordSession.choices=makeWordQuestion(bankMap.get(wordSession.ids[wordSession.i]));render();window.scrollTo(0,0)}
function revealWordCard(){wordSession.revealed=true;render()}
function exitWordSession(){wordSession=null;render();window.scrollTo(0,0)}
function stepResult(s){if(!s.step)return '';if(s.kind==='cards')return `<div class="x-step-result"><p>ステップ ${s.step.n} の${s.step.ids.length}語をカードで確認しました。確認テストで全問正解すると、次のステップに進めます。</p><button class="btn" onclick="startStep('quiz')">確認テスト →</button></div>`;
 if(s.stepCleared===undefined)s.stepCleared=s.results.length>0&&s.results.every(x=>x.correct)&&completeStep(s);
 return s.stepCleared?`<div class="x-step-result is-complete"><p><b>ステップ ${s.step.n} クリア！</b>${stepsToday()>=wordState.stepsPerDay?' 今日の分は完了です。':''}</p>${wordState.stepWords<stepLimit()?`<button class="btn" onclick="startStep('cards')">次のステップへ →</button>`:''}</div>`:`<div class="x-step-result"><p>全問正解でステップ ${s.step.n} をクリアできます。間違えた語を見直して、もう一度。</p><button class="btn" onclick="startStep('quiz')">もう一度テスト</button></div>`}
function wordSessionView(){const s=wordSession;if(s.i>=s.ids.length){const ok=s.results.filter(x=>x.correct).length,wrong=s.results.filter(x=>!x.correct).map(x=>x.id);return `<div class="w-session"><div class="w-result"><h1>${ok}<small> / ${s.ids.length}</small></h1><h2>${s.kind==='cards'?'思い出せた語':'正解'}</h2><p>${wrong.length?'間違えた語を復習対象にしました。もう一度、意味を思い出してみよう。':'次は日を空けて思い出してみよう。復習時期を記録しました。'}</p>${stepResult(s)}<div class="settings-row">${wrong.length?`<button class="btn" onclick="startWords('${s.kind}',${esc(JSON.stringify(wrong))})">${wrong.length}語をやり直す</button>`:''}<button class="btn light" onclick="exitWordSession()">単語帳へ戻る</button></div></div></div>`}const w=topicWord(bankMap.get(s.ids[s.i]),s.topic),r=wordRec(w.id),answered=s.answered!==null,correct=s.answered===w.id;return `<div class="w-session ${s.kind==='quiz'?'w-quiz-session':''}"><div class="w-session-top"><button class="textbtn" onclick="exitWordSession()">← 終了する</button><span>${s.i+1} / ${s.ids.length} 語</span><span>${s.kind==='cards'?'想起カード':s.mode==='listen'?'聞き取りテスト':'4択テスト'}</span></div><div class="track"><div style="width:${s.i/s.ids.length*100}%"></div></div><section class="w-flashcard ${s.kind==='quiz'?'w-quiz-card':''}">${wordMeta(w)}${s.kind==='cards'||s.mode==='th-ja'?`<div class="w-flash-th" lang="th">${esc(w.th)}</div><div class="w-flash-ro">${esc(w.ro)}</div>${wordAudio(w.id,'音声を聞く')}`:s.mode==='ja-th'?`<h2 class="w-ja-question">${esc(w.meanings[0].ja)}</h2>`:`<div class="w-listen-mark">${icon('audio')}</div>${wordAudio(w.id,'音声を聞く')}<p class="subtext">音を聞いて、いちばん近い意味を選ぼう。</p>`}${s.kind==='cards'?`${s.revealed?`<div class="w-card-answer">${w.meanings.map((m,i)=>`<section class="w-card-sense"><p class="w-card-meaning"><span class="w-card-meaning-no">${i+1}</span>${esc(m.ja)}${wordReference(m)}</p>${m.speechStyle?`<div class="w-card-style">${esc(m.speechStyle)}</div>`:''}${m.note?`<p class="w-usage-note">${esc(m.note)}</p>`:''}${wordSenseExample(w,m,i)}</section>`).join('')}<div class="w-card-rating"><button class="btn light" onclick="assessCard(false)">もう一度</button><button class="btn" onclick="assessCard(true)">思い出せた</button></div></div>`:`<p class="w-recall-hint">意味を思い出してから、答えを開こう。</p><button class="btn" onclick="revealWordCard()">意味・用例を確認する</button>`}`:`<div class="w-choices">${s.choices.map(id=>{const x=topicWord(bankMap.get(id),s.topic);return `<button class="option ${answered&&id===w.id?'correct':''} ${answered&&id===s.answered&&!correct?'wrong':''}" ${answered?'disabled':''} onclick="answerWord('${id}')">${s.mode==='ja-th'?`<span lang="th">${esc(x.th)}</span><small>${esc(x.ro)}</small>`:esc(x.meanings[0].ja)}</button>`}).join('')}</div>${answered?`<div class="feedback w-quiz-feedback ${correct?'':'bad'}" role="status"><div class="w-answer-summary"><strong>${correct?'正解！':'正解を確認'}</strong>${wordAudio(w.id,'発音を確認')}</div><div class="w-feedback-term"><span lang="th">${esc(w.th)}</span><b>${esc(w.ro)}</b></div><p>${esc(w.meanings[0].ja)}</p></div><div class="w-quiz-next"><button class="btn" onclick="nextWordQuestion()">${s.i===s.ids.length-1?'結果を見る':'次へ'} ${icon('arrow')}</button></div>`:''}`}</section><div class="w-session-bottom"><button class="btn light x-fav ${r.favorite?'chosen':''}" onclick="favoriteWord('${w.id}')" aria-label="お気に入り${r.favorite?'から外す':'に登録'}" aria-pressed="${r.favorite}" title="お気に入り">${icon('star')}</button><button class="btn light x-rev ${r.manual?'chosen':''}" onclick="reviewWord('${w.id}')" aria-label="復習${r.manual?'から外す':'に登録'}" aria-pressed="${r.manual}" title="復習に登録">${icon('review')}復習</button></div><p class="w-schedule-note">正解した語は1日→3日→7日→14日→30日→60日後へ。間違えた語はすぐ復習できます。手動で復習登録した語は、解除するまで残ります。</p></div>`}

function sanitizeWordState(input){input=input&&typeof input==='object'?input:{};const out=freshWordState();const count=(n,max=Number.MAX_SAFE_INTEGER)=>Number.isFinite(Number(n))?Math.max(0,Math.min(max,Math.floor(Number(n)))):0;{const lv=migrateLevel(input.level);if([0,...WORD_LEVELS.map(([n])=>n)].includes(lv))out.level=lv}if([5,10,20].includes(input.dailyGoal))out.dailyGoal=input.dailyGoal;out.stepWords=count(input.stepWords,100000);if(input.autoplay===false)out.autoplay=false;if([1,2,3].includes(input.stepsPerDay))out.stepsPerDay=input.stepsPerDay;const day=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)?s:'';if(input.today&&typeof input.today==='object')out.today={date:day(input.today.date),steps:count(input.today.steps,99)};if(input.streak&&typeof input.streak==='object')out.streak={last:day(input.streak.last),days:count(input.streak.days,100000)};for(const [id,r]of Object.entries(input.records||{})){if(!/^tl-\d+$/.test(id)||!r||typeof r!=='object')continue;out.records[id]={favorite:!!r.favorite,manual:!!r.manual,stage:count(r.stage,6),seen:count(r.seen),correct:count(r.correct),wrong:count(r.wrong),lapses:count(r.lapses),due:count(r.due),last:count(r.last)}}return out}
function resetWordData(){if(!confirm('単語の学習記録・お気に入り・復習登録をすべて消去します。よろしいですか？'))return;wordState=freshWordState();saveWords();wordCurrent=null;wordSession=null;render();toast('単語の学習記録をリセットしました。')}

function wordRegister(w){return w.collection==='slang'?`<p class="w-register-note">${w.adult?'下ネタ・大人の会話の学習欄です。':'友達の口語・スラングの学習欄です。'}「口語」は話し言葉中心、「スラング」は仲間内の特殊な言い方。粗さは相手との関係・口調でも変わります。</p>`:''}

function wordReference(s){return s.checked?'':`<small class="w-reference" title="追加確認が済むまでテストには出題しません。">${s.reviewStatus==='needs-source'?'要確認':'参考訳'}</small>`}

// Load examples on demand; ordinary word browsing stays compact.
let senseExamples=null,senseExamplesStatus='idle';
async function loadSenseExamples(){if(['loading','ready'].includes(senseExamplesStatus))return;senseExamplesStatus='loading';try{const rs=await Promise.all([fetch('sense-examples.json'),fetch('slang-examples.json')]);if(rs.some(r=>!r.ok))throw Error();const [base,extra]=await Promise.all(rs.map(r=>r.json()));const more=await loadOptionalJSON('more-examples.json',{});if(!base||typeof base!=='object'||!Object.keys(base).length||!more||typeof more!=='object'||Object.values({...base,...more,...extra}).some(e=>!e||!e.th||!e.ja))throw Error();senseExamples={...base,...more,...extra};senseExamplesStatus='ready'}catch{senseExamplesStatus='error'}if(view==='words'&&((wordCurrent&&!wordSession)||(wordSession?.kind==='cards'&&wordSession.revealed)))render()}
// Example sentences split into registered words. A split is shown only when every Thai letter belongs to a
// registered word and the word readings line up with the sentence's own romanization (syllable count and
// initial consonants), so a guess is never shown as fact.
let segBank=null,segIndex=null,segMax=1;const segCache=new Map();
function segEntries(){if(segBank!==bank){segBank=bank;segIndex=new Map();segMax=1;segCache.clear();for(const x of bank){if(x.generalHidden)continue;const cur=segIndex.get(x.th),xs=x.collection==='slang',cs=cur&&cur.collection==='slang';if(!cur||cs&&!xs||cs===xs&&x.frequency>cur.frequency)segIndex.set(x.th,x);if(x.th.length>segMax)segMax=x.th.length}}return segIndex}
const segSyl=r=>foldWord(r).replace(/[.,!?…"“”'‘’()「」:;]/g,' ').split(/\s+/).filter(Boolean),segOnset=x=>x.match(/^[^aeiou]*/)[0];
function segmentSentence(th,ro,prefer=''){const key=th+'\u0001'+ro+'\u0001'+prefer;if(segCache.has(key))return segCache.get(key);const idx=segEntries(),S=segSyl(ro),J=S.length,n=th.length,INF=1e9;
 const cost=Array.from({length:n+1},()=>new Array(J+1).fill(INF)),back=Array.from({length:n+1},()=>new Array(J+1).fill(null));cost[0][0]=0;
 const relax=(i,j,i2,j2,c,step)=>{if(i2>n||j2>J)return;const v=cost[i][j]+c;if(v<cost[i2][j2]){cost[i2][j2]=v;back[i2][j2]={i,j,...step}}};
 for(let i=0;i<n;i++)for(let j=0;j<=J;j++){if(cost[i][j]>=INF)continue;const ch=th[i];
  if(/[\s.,!?…"“”'‘’()「」:;\-]/.test(ch)){relax(i,j,i+1,j,0,{kind:'sep'});continue}
  if(ch==='ๆ'){for(let k=1;k<=3;k++)relax(i,j,i+1,j+k,1,{kind:'rep'});continue}
  if(/[0-9A-Za-z๐-๙]/.test(ch)){let e=i;while(e<n&&/[0-9A-Za-z๐-๙.,]/.test(th[e]))e++;for(let k=1;k<=5;k++)relax(i,j,e,j+k,2,{kind:'other'});continue}
  for(let L=1;L<=segMax&&i+L<=n;L++){const x=idx.get(th.slice(i,i+L));if(!x)continue;const ws=segSyl(x.ro),k=ws.length;if(!k||j+k>J)continue;const ok=ws.every((y,q)=>segOnset(y)===segOnset(S[j+q]));relax(i,j,i+L,j+k,(ok?1:4)-(x.th===prefer?1.1:0),{kind:'word',w:x,aligned:ok})}
  relax(i,j,i+1,j,30,{kind:'unknown'})}
 let out=null;if(cost[n][J]<INF){const toks=[];let i=n,j=J;while(i>0||j>0){const b=back[i][j];if(!b)break;toks.push({...b,th:th.slice(b.i,i),ro:S.slice(b.j,j).join(' '),sro:ro});i=b.i;j=b.j}toks.reverse();if(toks.every(t=>t.kind!=='unknown')&&toks.some(t=>t.kind==='word'))out=toks.filter(t=>t.kind!=='sep')}
 segCache.set(key,out);return out}
function segRomaji(t,ro){// the token's own syllables from the sentence romanization keep tones as written there
 const raw=ro.replace(/[.,!?…"“”'‘’()「」:;]/g,' ').split(/\s+/).filter(Boolean);return raw}
function exampleBreakdown(th,ro,prefer=''){if(bankStatus!=='ready')return '';const toks=segmentSentence(th,ro,prefer);if(!toks||toks.filter(t=>t.kind==='word').length<2)return '';const raw=segRomaji(null,ro);let pos=0;const nav=!wordSession&&!stepSession;
 const chips=toks.map(t=>{const k=t.kind==='word'?segSyl(t.w.ro).length:t.ro.split(' ').filter(Boolean).length,r=raw.slice(pos,pos+k).join(' ');pos+=k;if(t.kind!=='word')return `<span class="w-seg-chip is-plain"><b lang="th-Latn">${esc(r)}</b><span lang="th">${esc(t.th)}</span></span>`;const x=t.w,gloss=esc(shortGloss(x)),inner=`<b lang="th-Latn">${esc(t.aligned?r:x.ro)}</b><span lang="th">${esc(t.th)}</span><small>${gloss}</small>`;return nav?`<button type="button" class="w-seg-chip" onclick="openWord('${x.id}')" aria-label="${esc(x.th)}（${gloss}）を開く">${inner}</button>`:`<button type="button" class="w-seg-chip" data-th="${esc(x.th)}" onclick="speakThaiText(this.dataset.th)" aria-label="${esc(x.th)}（${gloss}）の発音">${inner}</button>`}).join('');
 return `<details class="w-seg"><summary>単語に分解</summary><div class="w-seg-row">${chips}</div><p class="w-seg-note">${nav?'押すとその単語へ移動します。':'押すと発音します。'}登録語で区切っています。</p></details>`}
// Grammar lessons keep their hand-made word panel; each word that is in the dictionary gets a link to it.
function fillDictLinks(panel){if(!panel)return;const run=()=>{const idx=segEntries();panel.querySelectorAll('.word-item').forEach(it=>{if(it.querySelector('.word-dict'))return;const th=(it.querySelector('.word-th')?.textContent||'').trim(),x=th&&idx.get(th);if(!x||x.collection==='slang')return;const b=document.createElement('button');b.type='button';b.className='textbtn word-dict';b.textContent='辞書で見る →';b.setAttribute('aria-label',th+'を辞書で見る');b.onclick=()=>openDictWord(x.id);(it.querySelector('.word-meaning')||it).appendChild(b)})};if(bankStatus==='ready')run();else loadWordBank().then(()=>{if(bankStatus==='ready')run()})}
function openDictWord(id){keepSearch=false;go('words');openWord(id)}
function wordSenseExample(w,s,i){if(senseExamplesStatus==='idle')loadSenseExamples();if(senseExamplesStatus==='error')return `<div class="w-example"><p>用例を読み込めませんでした。</p><button class="textbtn" onclick="senseExamplesStatus='idle';render()">もう一度読み込む</button></div>`;const e=senseExamples?.[w.id+'#'+s.sourceSense];if(!e)return `<div class="w-example" role="status">用例を読み込んでいます…</div>`;return `<div class="w-example"><div class="w-example-top"><span>この意味の用例${e.speechStyle?` <b class="w-example-style">${esc(e.speechStyle)}</b>`:''}</span><div><button class="w-audio" aria-label="意味${i+1}の用例を再生" onclick="playSenseExample('${w.id}',${s.sourceSense},false)" title="用例の発音">${icon('audio')}</button></div></div>${e.context?`<p class="w-example-context">${esc(e.context)}</p>`:''}<p class="w-example-th" lang="th">${esc(e.th)}</p><p class="w-example-ro" lang="th-Latn">${esc(e.ro)}</p><p class="w-example-ja">${esc(e.ja)}${e.checked?'':'<small class="w-reference" title="用例の日本語は未校閲の参考訳です。">参考訳</small>'}</p>${exampleBreakdown(e.th,e.ro,w.th)}${e.checked?'':`<details class="w-example-original"><summary>元の英語訳を確認</summary><p>${esc(e.en)}</p></details>`}</div>`}
function playSenseExample(id,n,slow=false){const e=senseExamples?.[id+'#'+n];if(e)speakThaiText(e.speechText||e.th,slow)}
// Guided step session, built on how memory consolidates:
//  1. spaced retrieval — words whose review date has come are tested first (expanding 1→3→7→14→30→60-day gaps);
//  2. encoding with sound and context — each new word is shown with audio, meaning and an example sentence;
//  3. retrieval practice — the new words are then recalled, Thai→Japanese, then Japanese→Thai (both directions);
//  4. within-session relearning — a missed item comes back a few items later until it is answered correctly;
//  5. sleep and spacing — a new word answered right first time is next reviewed tomorrow, a missed one sooner.
let stepSession=null;
const STEP_PHASES={review:'復習',learn:'新しい語',recall:'思い出す',produce:'タイ語で答える'};
function quizzable(w){return w&&w.meanings[0]?.checked}
function startGuidedStep(topic=''){if(bankStatus!=='ready')return;topic=allTopics().some(t=>t.id===topic)&&!SLANG_NO_STEP.has(topic)?topic:'';const tdeck=topic?topicDeck(topic):'general';const news=topic?topicNextWords(topic):nextStepWords();if(senseExamplesStatus==='idle')loadSenseExamples();
 const due=bank.filter(w=>wordInDeck(w,tdeck)&&(!topic||topicHas(w,topic)&&(tdeck!=='general'||wordInLevel(w)))&&dueWord(w)&&quizzable(topicWord(w,topic))&&!news.includes(w)).sort((a,b)=>(wordRec(a.id).due||0)-(wordRec(b.id).due||0)).slice(0,15);
 if(!news.length&&!due.length)return;wordTopic=topic;const q=news.filter(w=>quizzable(topicWord(w,topic))),tasks=[...due.map(w=>({id:w.id,type:'review'})),...news.map(w=>({id:w.id,type:'learn'})),...shuffle(q).map(w=>({id:w.id,type:'recall'})),...shuffle(q).map(w=>({id:w.id,type:'produce'}))];
 stepSession={topic,from:wordState.stepWords,n:stepNumber(),news:news.map(w=>w.id),tasks,i:0,answered:null,choices:null,missed:{},firstReview:{},done:false};prepareStepTask();wordCurrent=null;wordSession=null;render();window.scrollTo(0,0)}
function prepareStepTask(){const s=stepSession,t=s.tasks[s.i];s.answered=null;s.choices=t&&t.type!=='learn'?makeWordQuestion(stepWord(t.id)):null;if(t&&(t.type==='learn'||t.type==='recall'||t.type==='review'))setTimeout(()=>{if(stepSession&&stepSession.tasks[stepSession.i]===t&&wordState.autoplay!==false){const w=bankMap.get(t.id);if(w)speakThaiText(w.speechText||w.th,false,true)}},250)}
function answerStepTask(id){const s=stepSession,t=s.tasks[s.i];if(!t||s.answered!==null)return;s.answered=id;const ok=id===t.id;
 if(t.type==='review'&&!(t.id in s.firstReview)){s.firstReview[t.id]=ok;applyWordResult(t.id,ok)}
 if(!ok){if(t.type!=='review')s.missed[t.id]=true;s.tasks.splice(Math.min(s.i+4,s.tasks.length),0,{...t,retry:true})}
 if((t.type==='produce'||ok)&&wordState.autoplay!==false){const w=bankMap.get(t.id);if(w)speakThaiText(w.speechText||w.th,false,true)}render()}
function nextStepTask(){const s=stepSession;s.i++;if(s.i>=s.tasks.length)finishGuidedStep();else prepareStepTask();render();window.scrollTo(0,0)}
function finishGuidedStep(){const s=stepSession;if(s.done)return;s.done=true;for(const id of s.news)applyWordResult(id,!s.missed[id]);if(s.topic){markStudyDay();s.cleared=true}else s.cleared=completeStep({step:{from:s.from,ids:s.news}})}
function stepWord(id){return topicWord(bankMap.get(id),stepSession?.topic||'')}
function exitStepSession(){stepSession=null;render();window.scrollTo(0,0)}
function stepWordFace(w,size=''){return `<div class="g-face ${size}"><span class="g-ro" lang="th-Latn">${esc(w.ro)}</span><span class="g-th" lang="th">${esc(w.th)}</span></div>`}
function stepSessionView(){const s=stepSession,total=s.tasks.length;
 if(s.done){const missed=s.news.filter(id=>s.missed[id]).length,reviewed=Object.keys(s.firstReview).length,reviewOk=Object.values(s.firstReview).filter(Boolean).length;const tp=s.topic&&allTopics().find(x=>x.id===s.topic),more=tp?topicNextWords(tp.id).length>0:wordState.stepWords<stepLimit();return `<div class="w-session"><div class="w-result g-result">${tp?`<div class="g-topic-mark">${topicIcon(tp.id,'is-large')}</div><div class="eyebrow">テーマ</div><h1>${esc(tp.label)} 完了</h1>`:`<div class="eyebrow">STEP ${s.n}</div><h1>ステップ ${s.n} 完了</h1>`}<ul class="g-summary"><li>新しい語 <b>${s.news.length}</b>語${missed?`（うち ${missed}語は一度間違えたので、早めにもう一度出します）`:'（全部1回目で正解）'}</li>${reviewed?`<li>復習 <b>${reviewOk}</b> / ${reviewed}語 正解</li>`:''}<li>次の復習：${missed?'近いうち':'明日'}。間隔を空けて思い出すほど記憶に残ります。</li></ul>${stepsToday()>=wordState.stepsPerDay?'<p class="g-done">✓ 今日の分は完了。続けるより、明日の復習で思い出すほうが定着します。</p>':''}<div class="settings-row">${more?`<button class="btn${stepsToday()>=wordState.stepsPerDay?' light':''}" onclick="startGuidedStep('${tp?tp.id:''}')">${tp?'このテーマの続きへ':'次のステップへ'} →</button>`:''}<button class="btn${stepsToday()>=wordState.stepsPerDay?'':' light'}" onclick="exitStepSession()">単語帳へ戻る</button></div></div></div>`}
 const t=s.tasks[s.i],w=stepWord(t.id),answered=s.answered!==null,ok=s.answered===t.id,phase=STEP_PHASES[t.type];
 const head=`<div class="w-session-top"><button class="textbtn" onclick="exitStepSession()">← 中断する</button><span>${s.i+1} / ${total}</span><span class="g-phase g-${t.type}">${phase}${t.retry?' · もう一度':''}</span></div><div class="track"><div style="width:${s.i/total*100}%"></div></div>`;
 if(t.type==='learn'){const ms=w.meanings.filter(m=>!m.isSlang).slice(0,2);return `<div class="w-session">${head}<section class="w-flashcard g-card">${stepWordFace(w,'is-large')}<div class="g-audio">${wordAudio(w.id,'発音')}</div><div class="g-meanings">${ms.map((m,i)=>`<div class="g-meaning"><b>${esc(m.ja)}</b><small>${esc(m.pos)}</small>${wordSenseExample(w,m,i)}</div>`).join('')}</div><p class="g-tip">声に出してまねしてから次へ。このあと思い出すテストがあります。</p><div class="w-session-bottom"><button class="btn" onclick="nextStepTask()">覚えた → 次へ</button></div></section></div>`}
 const opts=s.choices.map(id=>stepWord(id)),produce=t.type==='produce';
 return `<div class="w-session w-quiz-session">${head}<section class="w-flashcard w-quiz-card g-card">${produce?`<h2 class="g-prompt">${esc(w.meanings[0].ja)}</h2><p class="g-ask">タイ語では？</p>`:`${stepWordFace(w)}<div class="g-audio">${wordAudio(w.id,'発音')}</div><p class="g-ask">意味は？</p>`}<div class="g-options">${opts.map(o=>`<button class="option g-option ${answered&&o.id===t.id?'correct':''} ${answered&&o.id===s.answered&&!ok?'wrong':''}" ${answered?'disabled':''} onclick="answerStepTask('${o.id}')">${produce?stepWordFace(o,'is-small'):`<span>${esc(o.meanings[0].ja)}</span>`}</button>`).join('')}</div>${answered?`<div class="feedback ${ok?'':'bad'}" role="status"><strong>${ok?'正解！':'惜しい。少しあとでもう一度出します。'}</strong>${produce||!ok?`<br><span class="g-answer">${esc(w.ro)}（${esc(w.th)}）＝ ${esc(w.meanings[0].ja)}</span>`:''}</div><div class="w-session-bottom"><button class="btn" onclick="nextStepTask()">次へ →</button></div>`:''}</section></div>`}
